int getLength(String? text) {
  return text?.length ?? 0;
}

void main() {
  print('Độ dài của Hello: ${getLength('Hello')}');
  print('Độ dài của null: ${getLength(null)}');
  print('Độ dài của chuỗi rỗng: ${getLength('')}');
}

String createUser({required String name, int age = 0, String? email}) {
  final emailStr = email ?? 'none';
  return 'User: $name, Age: $age, Email: $emailStr';
}

void main() {
  print(createUser(name: 'Alice'));
  print(createUser(name: 'Bob', age: 25));
  print(createUser(name: 'Carol', age: 30, email: 'c@ex.com'));
}

String getUpperCase(String? text) {
  if (text == null) {
    throw Exception('Text cannot be null');
  }
  return text!.toUpperCase();
}

void main() {
  print('In hoa hello: ${getUpperCase('hello')}');
  print('In hoa dart: ${getUpperCase('dart')}');
}

